from dataclasses import dataclass

@dataclass
class Student:
    name: str
    marks: int = 0

print(Student('Ashu', 95))

class Product:
    def __init__(self, price):
        self.price = price
    @property
    def price(self):
        return self._price
    @price.setter
    def price(self, value):
        if value < 0:
            raise ValueError('price must be >= 0')
        self._price = value

class User:
    def __init__(self, name, email):
        self.name, self.email = name, email

    @classmethod
    def from_row(cls, row):
        return cls(row[0].strip(), row[1].strip().lower())

user = User.from_row([' Ashu ', 'A@X.COM'])

class Money:
    def __init__(self, amount, currency):
        self.amount, self.currency = amount, currency
    def __eq__(self, other):
        return isinstance(other, Money) and (self.amount, self.currency) == (other.amount, other.currency)
    def __hash__(self):
        return hash((self.amount, self.currency))

class Account:
    def __init__(self, balance=0):
        self.balance, self.log = balance, []
    def deposit(self, amt):
        if amt <= 0: raise ValueError('amount must be positive')
        self.balance += amt
        self.log.append(('deposit', amt, self.balance))
    def withdraw(self, amt):
        if amt > self.balance: raise ValueError('insufficient funds')
        self.balance -= amt
        self.log.append(('withdraw', amt, self.balance))

class Registry:
    def __init__(self):
        self._items = {}
    def register(self, name):
        def wrap(fn):
            if name in self._items:
                raise ValueError(f'duplicate plugin {name}')
            self._items[name] = fn
            return fn
        return wrap

reg = Registry()
@reg.register('csv')
def load_csv(path): return []

from abc import ABC, abstractmethod

class Payment(ABC):
    @abstractmethod
    def pay(self, amount): ...

class Card(Payment):
    def pay(self, amount): return f'card:{amount}'

def checkout(method: Payment, amount):
    return method.pay(amount)
